import java.io.*;import java.nio.file.*;import java.sql.*;import java.util.*;
public class CO5Solutions{
 static class PassStore{final Path file;PassStore(Path p){file=p;}void add(String id,String reg,String name,int route,double amount)throws IOException{try(BufferedWriter w=Files.newBufferedWriter(file,StandardOpenOption.CREATE,StandardOpenOption.APPEND)){w.write(String.join(",",id,reg,name,String.valueOf(route),String.valueOf(amount)));w.newLine();}}String[]find(String id)throws IOException{if(!Files.exists(file))return null;try(BufferedReader r=Files.newBufferedReader(file)){String line;while((line=r.readLine())!=null){String[]p=line.split(",",-1);if(p.length!=5)continue;if(p[0].equals(id))return p;}}return null;}}
 static long countBuffered(Path p)throws IOException{long n=0;try(BufferedReader r=Files.newBufferedReader(p)){while(r.readLine()!=null)n++;}return n;}
 static long countBytewise(Path p)throws IOException{long n=0;try(InputStream in=Files.newInputStream(p)){int b;while((b=in.read())!=-1)if(b=='\n')n++;}return n;}
 interface Dao<T,K>{void insert(T x)throws SQLException;Optional<T>findById(K id)throws SQLException;List<T>findAll()throws SQLException;void update(T x)throws SQLException;void delete(K id)throws SQLException;}
 record Student(int id,String name,String email){}
 static class StudentDao implements Dao<Student,Integer>{final Connection c;StudentDao(Connection c){this.c=c;}public void insert(Student s)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT INTO student VALUES(?,?,?)")){p.setInt(1,s.id());p.setString(2,s.name());p.setString(3,s.email());p.executeUpdate();}}public Optional<Student>findById(Integer id)throws SQLException{try(PreparedStatement p=c.prepareStatement("SELECT id,name,email FROM student WHERE id=?")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){return r.next()?Optional.of(new Student(r.getInt(1),r.getString(2),r.getString(3))):Optional.empty();}}}public List<Student>findAll()throws SQLException{List<Student>x=new ArrayList<>();try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT id,name,email FROM student")){while(r.next())x.add(new Student(r.getInt(1),r.getString(2),r.getString(3)));}return x;}public void update(Student s)throws SQLException{try(PreparedStatement p=c.prepareStatement("UPDATE student SET name=?,email=? WHERE id=?")){p.setString(1,s.name());p.setString(2,s.email());p.setInt(3,s.id());p.executeUpdate();}}public void delete(Integer id)throws SQLException{try(PreparedStatement p=c.prepareStatement("DELETE FROM student WHERE id=?")){p.setInt(1,id);p.executeUpdate();}}}
 static class Resident implements Serializable{private static final long serialVersionUID=1L;String name,regNo,phone;transient String password;transient Connection liveConnection;Resident(String n,String r,String p){name=n;regNo=r;password=p;}}
 static void transfer(Connection c,int from,int to,double amount)throws SQLException{if(amount<=0)throw new IllegalArgumentException();boolean old=c.getAutoCommit();c.setAutoCommit(false);try(PreparedStatement d=c.prepareStatement("UPDATE wallet SET balance=balance-? WHERE id=? AND balance>=?");PreparedStatement cr=c.prepareStatement("UPDATE wallet SET balance=balance+? WHERE id=?")){d.setDouble(1,amount);d.setInt(2,from);d.setDouble(3,amount);if(d.executeUpdate()!=1)throw new SQLException("Insufficient funds");cr.setDouble(1,amount);cr.setInt(2,to);if(cr.executeUpdate()!=1)throw new SQLException("Destination missing");c.commit();}catch(SQLException e){c.rollback();throw e;}finally{c.setAutoCommit(old);}}
 static int loadBatch(Connection c,List<String[]>rows)throws SQLException{String sql="INSERT INTO bus_pass(pass_id,reg_no,name,route_no,amount) VALUES(?,?,?,?,?)";boolean old=c.getAutoCommit();c.setAutoCommit(false);int n=0;try(PreparedStatement p=c.prepareStatement(sql)){for(String[]r:rows){p.setString(1,r[0]);p.setString(2,r[1]);p.setString(3,r[2]);p.setInt(4,Integer.parseInt(r[3]));p.setDouble(5,Double.parseDouble(r[4]));p.addBatch();n++;if(n%1000==0)p.executeBatch();}p.executeBatch();c.commit();return n;}catch(Exception e){c.rollback();if(e instanceof SQLException s)throw s;throw new SQLException("Invalid pass",e);}finally{c.setAutoCommit(old);}}
 public static void main(String[]a)throws Exception{Path f=Files.createTempFile("passes",".csv");PassStore s=new PassStore(f);s.add("P1001","192311001","Arun",12,4500);Files.writeString(f,"P1002,DAMAGED LINE\n",StandardOpenOption.APPEND);s.add("P1003","192311003","Divya",7,3800);System.out.println(Arrays.toString(s.find("P1003")));System.out.println(Arrays.toString(s.find("P1002")));System.out.println("Lines "+countBuffered(f));}
}